use vstd::prelude::*;

verus! {
    fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> (result: Vec<T>)
        requires
            0 <= idx && idx <= arr.len(),
        ensures
            result.len() == arr.len() + 1,
            forall|j: usize| (j < idx ==> result[j] == arr[j]) &&
            (j >= idx ==> result[j + 1] == arr[j]),
            result[idx] == value,
    {
        let mut result: Vec<T> = Vec::with_capacity(arr.len() + 1);
        let mut i: usize = 0;

        // Fill the result array with elements from arr
        while i < arr.len()
            invariant
                i <= arr.len(),
                result.len() == i + 1,
                forall|j: usize| (j < idx ==> result[j] == arr[j]) &&
                (j >= idx ==> result[j + 1] == arr[j]),
            decreases arr.len() - i,
        {
            if i == idx {
                result.push(value); // Insert the new value at the specified index
            }
            result.push(arr[i]); // Copy the current element from arr
            i = i + 1;
        }

        // If idx is equal to arr.len(), we need to insert the value at the end
        if idx == arr.len() {
            result.push(value);
        }

        result
    }
}
